window.AUTH=window.AUTH||{};window.AUTH["87-1703"]={"d":"87-1703","id":"1988/87-1703","n":"Robertson v. Methow Valley Citizens Council","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioners","date":"","url":"https://www.justice.gov/osg/media/209516/dl?inline","side":"pet","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/f-dale-robertson-chief-forest-service-et-al-petitioners-v-methow-valley-citizens-council","toa":false,"n":45}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep490/usrep490332/usrep490332.pdf","tr":false,"items":[{"t":"case","label":"Baltimore Gas & Elec. Co. v. Natural Resources Defense Council, Inc.","cite":"462 U.S. 87","y":1983,"id":"1982/82-524","sc":1,"op":3,"sum":"The NRC complied with NEPA, and its decision is not arbitrary or capricious within the meaning of § 10(e) of the Administrative Procedure Act (APA).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"op":2,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Kleppe v. Sierra Club","cite":"427 U.S. 390","id":"1975/75-552","sc":1,"op":4,"sum":"Section 102 (2) (C) of the National Environmental Policy Act of 1969 (NEPA) requires that all federal agencies include an environmental impact statement (EIS) \"in every recommendation or report on proposals for legislation and other major Federal actions significantly affecting the quality of the human environment.\" Respondent environmental organizations, alleging a widespread interest in the rich coal reserves of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Lyng v. Payne","cite":"476 U.S. 926","y":1986,"id":"1985/84-1948","sc":1,"op":1,"sum":"Under the Consolidated Farm and Rural Development Act, the Secretary of Agriculture has authority to make emergency loans to farmers who suffer economic losses as a result of a natural disaster. Pursuant to a rule of the Farmers Home Administration (FmHA), the Secretary required loan applicants suffering from disasters occurring between December 26, 1972, and April 20, 1973, to file their applications by April 2, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Andrus v. Sierra Club","cite":"442 U.S. 347","y":1979,"id":"1978/78-625","sc":1,"op":3,"sum":"Section 102 (2) (C) does not require federal agencies to prepare EIS's to accompany appropriation requests.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Stop H-3 Ass'n. v. Brinegar","cite":"389 F. Supp. 1102","y":1974,"court":"D. Haw.","url":"https://www.courtlistener.com/c/F.%20Supp./389/1102/","op":2,"by":{"0":""}},{"t":"case","label":"Weinberger v. Catholic Action","cite":"454 U.S. 139","y":1981,"id":"1981/81-1377","sc":1,"op":1,"sum":"The Court of Appeals erred in requiring the Navy to prepare and release to the public a \"Hypothetical Environmental Impact Statement.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Strycker's Bay Neighborhood Council, Inc. v. Karlen","cite":"444 U.S. 223","y":1980,"id":"1979/79-168","sc":1,"op":2,"sum":"The Court of Appeals erred in concluding that when the Department of Housing and Urban Development (HUD) considered alternative sites before redesignating a proposed site for middle-income housing as one for low-income housing it should have given determinative weight to environmental factors such as crowding low-income housing into a concentrated area and should not have considered the delay that would occur in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"City of New York v. United States Dep't of Transportation","cite":"715 F.2d 732","url":"https://www.courtlistener.com/c/F.2d/715/732/","op":1,"by":{"0":""}},{"t":"case","label":"Friends of Endangered Species, Inc. v. Jantzen","cite":"760 F.2d 976","y":1985,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/760/976/","op":1,"by":{"0":""}},{"t":"case","label":"Concerned Citizens on I-190 v. Secretary of Transportation","cite":"641 F.2d 1","y":1981,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/641/1/","by":{"0":""}},{"t":"case","label":"Save Our Ecosystems v. Clark","cite":"747 F.2d 1240","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/747/1240/","op":1,"by":{"0":""}},{"t":"case","label":"Sierra Club v. Sigler","cite":"695 F.2d 957","url":"https://www.courtlistener.com/c/F.2d/695/957/","op":1,"sum":"Recognizing that NEPA requires adherence to CEQ regulations, even when CEQ changes its interpretation, and that CEQ regulations are entitled to substantial deference.","sumSrc":"brief:0","by":{"0":""}},{"t":"case","label":"Trout Unlimited v. Morton","cite":"509 F.2d 1276","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/509/1276/","by":{"0":""}},{"t":"case","label":"American Trucking Ass'ns v. Atchison, T. & S.F. Ry.","cite":"387 U.S. 397","y":1967,"id":"1966/57","sc":1,"sum":"1. \"[I]n light of the mandate of the National Transportation Policy, the Commission had authority derived from the commoncarrier obligations of the railroads as reflected in §§ 1 (4), 2, and 3 (1) of the Interstate Commerce Act to promulgate Rule 2 requiring that any railroad offering TOFC service through its open-tariff publications must make that service available 'to any person' on nondiscriminatory terms.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Larionoff","cite":"431 U.S. 864","y":1977,"id":"1976/76-413","sc":1,"sum":"Respondent enlisted members of the United States Navy and others sumlarly situated, who agreed to extend their enlistments at a time when a statute provided for a Variable Re-enlistment Bonus (VRB), m addition to the Regular Re-enlistment Bonus (RRB), for members of the Armed Forces whose ratings were classified as a \"critical military skill\" held entitled to VRB's determined according to the award level m effect at …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Bowles v. Seminole Rock & Sand Co.","cite":"325 U.S. 410","y":1945,"id":"scdb/1944-069","sc":1,"op":1,"by":{"0":""}},{"t":"case","label":"Anderson v. City of Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Roosevelt Campobello Int'l Park v. EPA","cite":"684 F.2d 1041","y":1982,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/684/1041/","by":{"0":""}},{"t":"case","label":"Scientists' Inst. for Pub. Information, Inc. v. AEC","cite":"481 F.2d 1079","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/481/1079/","by":{"0":""}},{"t":"case","label":"Louisiana v. Lee","cite":"758 F.2d 1081","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/758/1081/","by":{"0":""}},{"t":"case","label":"Scotchman's Peak Grizzly Bears v. Peterson","cite":"685 F.2d 678","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/685/678/","by":{"0":""}},{"t":"case","label":"Preservation Coalition, Inc. v. Pierce","cite":"667 F.2d 851","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/667/851/","op":1,"by":{"0":""}},{"t":"case","label":"City & County of San Francisco v. United States","cite":"615 F.2d 498","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/615/498/","by":{"0":""}},{"t":"case","label":"Maryland-National Capital Park & Planning Comm'n v. U.S. Postal Service","cite":"487 F.2d 1029","y":1973,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/487/1029/","by":{"0":""}},{"t":"case","label":"Village of False Pass v. Clark","cite":"733 F.2d 605","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/733/605/","by":{"0":""}},{"t":"case","label":"Township of Springfield v. Lewis","cite":"702 F.2d 426","y":1983,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/702/426/","by":{"0":""}},{"t":"case","label":"National Indian Youth Council v. Watt","cite":"664 F.2d 220","y":1981,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/664/220/","op":1,"by":{"0":""}},{"t":"case","label":"County of Suffolk v. Secretary of the Interior","cite":"562 F.2d 1368","y":1977,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/562/1368/","by":{"0":""}},{"t":"case","label":"Carolina Envtl. Study Group v. United States","cite":"510 F.2d 796","y":1975,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/510/796/","op":2,"by":{"0":""}},{"t":"case","label":"Alaska v. Andrus","cite":"580 F.2d 465","y":1978,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/580/465/","op":1,"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 4332","url":"https://www.law.cornell.edu/uscode/text/42/4332","stext":{"head":"§4332. Cooperation of agencies; reports; availability of information; recommendations; international and national coordination of efforts","paras":[[0,"The Congress authorizes and directs that, to the fullest extent possible: (1) the policies, regulations, and public laws of the United States shall be interpreted and administered in accordance with the policies set forth in this chapter, and (2) all agencies of the Federal Government shall—"],[1,"(A) utilize a systematic, interdisciplinary approach which will ensure the integrated use of the natural and social sciences and the environmental design arts in planning and in decisionmaking which may have an impact on man's environment;"],[1,"(B) identify and develop methods and procedures, in consultation with the Council on Environmental Quality established by subchapter II of this chapter, which will ensure that presently unquantified environmental amenities and values may be given appropriate consideration in decisionmaking along with economic and technical considerations;"],[1,"(C) consistent with the provisions of this chapter and except where compliance would be inconsistent with other statutory requirements, include in every recommendation or report on proposals for legislation and other major Federal actions significantly affecting the quality of the human environment, a detailed statement by the responsible official on—"],[2,"(i) reasonably foreseeable environmental effects of the proposed agency action;"],[2,"(ii) any reasonably foreseeable adverse environmental effects which cannot be avoided should the proposal be implemented;"],[2,"(iii) a reasonable range of alternatives to the proposed agency action, including an analysis of any negative environmental impacts of not implementing the proposed agency action in the case of a no action alternative, that are technically and economically feasible, and meet the purpose and need of the proposal;"],[2,"(iv) the relationship between local short-term uses of man's environment and the maintenance and enhancement of long-term productivity; and"],[2,"(v) any irreversible and irretrievable commitments of Federal resources which would be involved in the proposed agency action should it be implemented."],[1,"Prior to making any detailed statement, the head of the lead agency shall consult with and obtain the comments of any Federal agency which has jurisdiction by law or special expertise with respect to any environmental impact involved. Copies of such statement and the comments and views of the appropriate Federal, State, and local agencies, which are authorized to develop and enforce environmental standards, shall be made available to the President, the Council on Environmental Quality and to the public as provided by section 552 of title 5, and shall accompany the proposal through the existing agency review processes;"],[1,"(D) ensure the professional integrity, including scientific integrity, of the discussion and analysis in an environmental document;"],[1,"(E) make use of reliable data and resources in carrying out this chapter;"],[1,"(F) consistent with the provisions of this chapter, study, develop, and describe technically and economically feasible alternatives;"],[1,"(G) any detailed statement required under subparagraph (C) after January 1, 1970, for any major Federal action funded under a program of grants to States shall not be deemed to be legally insufficient solely by reason of having been prepared by a State agency or official, if:"],[2,"(i) the State agency or official has statewide jurisdiction and has the responsibility for such action,"],[2,"(ii) the responsible Federal official furnishes guidance and participates in such preparation,"],[2,"(iii) the responsible Federal official independently evaluates such statement prior to its approval and adoption, and"],[2,"(iv) after January 1, 1976, the responsible Federal official provides early notification to, and solicits the views of, any other State or any Federal land management entity of any action or any alternative thereto which may have significant impacts upon such State or affected Federal land management entity and, if there is any disagreement on such impacts, prepares a written assessment of such impacts and views for incorporation into such detailed statement."],[1,"The procedures in this subparagraph shall not relieve the Federal official of his responsibilities for the scope, objectivity, and content of the entire statement or of any other responsibility under this chapter; and further, this subparagraph does not affect the legal sufficiency of statements prepared by State agencies with less than statewide jurisdiction.1"],[1,"(H) study, develop, and describe appropriate alternatives to recommended courses of action in any proposal which involves unresolved conflicts concerning alternative uses of available resources;"],[1,"(I) consistent with the provisions of this chapter, recognize the worldwide and long-range character of environmental problems and, where consistent with the foreign policy of the United States, lend appropriate support to initiatives, resolutions, and programs designed to maximize international cooperation in anticipating and preventing a decline in the quality of mankind's world environment;"],[1,"(J) make available to States, counties, municipalities, institutions, and individuals, advice and information useful in restoring, maintaining, and enhancing the quality of the environment;"],[1,"(K) initiate and utilize ecological information in the planning and development of resource-oriented projects; and"],[1,"(L) assist the Council on Environmental Quality established by subchapter II of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4332?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§4332. Cooperation of agencies; reports; availability of information; recommendations; international and national coordination of efforts","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 4321","url":"https://www.law.cornell.edu/uscode/text/42/4321","stext":{"head":"§4321. Congressional declaration of purpose","paras":[[0,"The purposes of this chapter are: To declare a national policy which will encourage productive and enjoyable harmony between man and his environment; to promote efforts which will prevent or eliminate damage to the environment and biosphere and stimulate the health and welfare of man; to enrich the understanding of the ecological systems and natural resources important to the Nation; and to establish a Council on Environmental Quality."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/4321?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4321. Congressional declaration of purpose","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 528","url":"https://www.law.cornell.edu/uscode/text/16/528","stext":{"head":"§528. Development and administration of renewable surface resources for multiple use and sustained yield of products and services; Congressional declaration of policy and purpose","paras":[[0,"It is the policy of the Congress that the national forests are established and shall be administered for outdoor recreation, range, timber, watershed, and wildlife and fish purposes. The purposes of sections 528 to 531 of this title are declared to be supplemental to, but not in derogation of, the purposes for which the national forests were established as set forth in section 475 of this title. Nothing herein shall be construed as affecting the jurisdiction or responsibilities of the several States with respect to wildlife and fish on the national forests. Nothing herein shall be construed so as to affect the use or administration of the mineral resources of national forest lands or to affect the use or administration of Federal lands not within national forests."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/528?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§528. Development and administration of renewable surface resources for multiple use and sustained yield of products and services; Congressional declaration of policy and purpose","tname":"Conservation","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 1600","url":"https://www.law.cornell.edu/uscode/text/16/1600","stext":{"head":"§1600. Congressional findings","paras":[[0,"The Congress finds that—"],[1,"(1) the management of the Nation's renewable resources is highly complex and the uses, demand for, and supply of the various resources are subject to change over time;"],[1,"(2) the public interest is served by the Forest Service, Department of Agriculture, in cooperation with other agencies, assessing the Nation's renewable resources, and developing and preparing a national renewable resource program, which is periodically reviewed and updated;"],[1,"(3) to serve the national interest, the renewable resource program must be based on a comprehensive assessment of present and anticipated uses, demand for, and supply of renewable resources from the Nation's public and private forests and rangelands, through analysis of environmental and economic impacts, coordination of multiple use and sustained yield opportunities as provided in the Multiple-Use Sustained-Yield Act of 1960 (74 Stat. 215; 16 U.S.C. 528–531), and public participation in the development of the program;"],[1,"(4) the new knowledge derived from coordinated public and private research programs will promote a sound technical and ecological base for effective management, use, and protection of the Nation's renewable resources;"],[1,"(5) inasmuch as the majority of the Nation's forests and rangeland is under private, State, and local governmental management and the Nation's major capacity to produce goods and services is based on these nonfederally managed renewable resources, the Federal Government should be a catalyst to encourage and assist these owners in the efficient long-term use and improvement of these lands and their renewable resources consistent with the principles of sustained yield and multiple use;"],[1,"(6) the Forest Service, by virtue of its statutory authority for management of the National Forest System, research and cooperative programs, and its role as an agency in the Department of Agriculture, has both a responsibility and an opportunity to be a leader in assuring that the Nation maintains a natural resource conservation posture that will meet the requirements of our people in perpetuity; and"],[1,"(7) recycled timber product materials are as much a part of our renewable forest resources as are the trees from which they originally came, and in order to extend our timber and timber fiber resources and reduce pressures for timber production from Federal lands, the Forest Service should expand its research in the use of recycled and waste timber product materials, develop techniques for the substitution of these secondary materials for primary materials, and promote and encourage the use of recycled timber product materials."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1600?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1600. Congressional findings","tname":"Conservation","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 90","url":"https://www.law.cornell.edu/uscode/text/16/90","stext":{"head":"§90. Establishment; statement of purposes; description of area","paras":[[0,"In order to preserve for the benefit, use, and inspiration of present and future generations certain majestic mountain scenery, snow fields, glaciers, alpine meadows, and other unique natural features in the North Cascade Mountains of the State of Washington, there is hereby established, subject to valid existing rights, the North Cascades National Park (hereinafter referred to in this subchapter as the \"park\"). The park shall consist of the lands, waters, and interests therein within the area designated \"national park\" on the map entitled \"Proposed Management Units, North Cascades, Washington,\" numbered NP–CAS–7002, and dated October 1967. The map shall be on file and available for public inspection in the office of the Director, National Park Service, Department of the Interior, and in the office of the Chief, Forest Service, Department of Agriculture."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/90?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§90. Establishment; statement of purposes; description of area","tname":"Conservation","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","stext":{"head":"§7401. Congressional findings and declaration of purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds—"],[1,"(1) that the predominant part of the Nation's population is located in its rapidly expanding metropolitan and other urban areas, which generally cross the boundary lines of local jurisdictions and often extend into two or more States;"],[1,"(2) that the growth in the amount and complexity of air pollution brought about by urbanization, industrial development, and the increasing use of motor vehicles, has resulted in mounting dangers to the public health and welfare, including injury to agricultural crops and livestock, damage to and the deterioration of property, and hazards to air and ground transportation;"],[1,"(3) that air pollution prevention (that is, the reduction or elimination, through any measures, of the amount of pollutants produced or created at the source) and air pollution control at its source is the primary responsibility of States and local governments; and"],[1,"(4) that Federal financial assistance and leadership is essential for the development of cooperative Federal, State, regional, and local programs to prevent and control air pollution."],[0,"(b) Declaration"],[0,"The purposes of this subchapter are—"],[1,"(1) to protect and enhance the quality of the Nation's air resources so as to promote the public health and welfare and the productive capacity of its population;"],[1,"(2) to initiate and accelerate a national research and development program to achieve the prevention and control of air pollution;"],[1,"(3) to provide technical and financial assistance to State and local governments in connection with the development and execution of their air pollution prevention and control programs; and"],[1,"(4) to encourage and assist the development and operation of regional air pollution prevention and control programs."],[0,"(c) Pollution prevention"],[0,"A primary goal of this chapter is to encourage or otherwise promote reasonable Federal, State, and local governmental actions, consistent with the provisions of this chapter, for pollution prevention."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7401. Congressional findings and declaration of purpose","tname":"The Public Health and Welfare","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 636","url":"https://www.law.cornell.edu/uscode/text/28/636","subs":["(c)"],"stext":{"head":"§636. Jurisdiction, powers, and temporary assignment","paras":[[0,"(a) Each United States magistrate judge serving under this chapter shall have within the district in which sessions are held by the court that appointed the magistrate judge, at other places where that court may function, and elsewhere as authorized by law—"],[1,"(1) all powers and duties conferred or imposed upon United States commissioners by law or by the Rules of Criminal Procedure for the United States District Courts;"],[1,"(2) the power to administer oaths and affirmations, issue orders pursuant to section 3142 of title 18 concerning release or detention of persons pending trial, and take acknowledgements, affidavits, and depositions;"],[1,"(3) the power to conduct trials under section 3401, title 18, United States Code, in conformity with and subject to the limitations of that section;"],[1,"(4) the power to enter a sentence for a petty offense; and"],[1,"(5) the power to enter a sentence for a class A misdemeanor in a case in which the parties have consented."],[0,"(b)(1) Notwithstanding any provision of law to the contrary—"],[1,"(A) a judge may designate a magistrate judge to hear and determine any pretrial matter pending before the court, except a motion for injunctive relief, for judgment on the pleadings, for summary judgment, to dismiss or quash an indictment or information made by the defendant, to suppress evidence in a criminal case, to dismiss or to permit maintenance of a class action, to dismiss for failure to state a claim upon which relief can be granted, and to involuntarily dismiss an action. A judge of the court may reconsider any pretrial matter under this subparagraph (A) where it has been shown that the magistrate judge's order is clearly erroneous or contrary to law."],[1,"(B) a judge may also designate a magistrate judge to conduct hearings, including evidentiary hearings, and to submit to a judge of the court proposed findings of fact and recommendations for the disposition, by a judge of the court, of any motion excepted in subparagraph (A), of applications for posttrial 1 relief made by individuals convicted of criminal offenses and of prisoner petitions challenging conditions of confinement."],[1,"(C) the magistrate judge shall file his proposed findings and recommendations under subparagraph (B) with the court and a copy shall forthwith be mailed to all parties."],[0,"Within fourteen days after being served with a copy, any party may serve and file written objections to such proposed findings and recommendations as provided by rules of court. A judge of the court shall make a de novo determination of those portions of the report or specified proposed findings or recommendations to which objection is made. A judge of the court may accept, reject, or modify, in whole or in part, the findings or recommendations made by the magistrate judge. The judge may also receive further evidence or recommit the matter to the magistrate judge with instructions."],[0,"(2) A judge may designate a magistrate judge to serve as a special master pursuant to the applicable provisions of this title and the Federal Rules of Civil Procedure for the United States district courts. A judge may designate a magistrate judge to serve as a special master in any civil case, upon consent of the parties, without regard to the provisions of rule 53(b) of the Federal Rules of Civil Procedure for the United States district courts."],[0,"(3) A magistrate judge may be assigned such additional duties as are not inconsistent with the Constitution and laws of the United States."],[0,"(4) Each district court shall establish rules pursuant to which the magistrate judges shall discharge their duties."],[0,"(c) Notwithstanding any provision of law to the contrary—"],[1,"(1) Upon the consent of the parties, a full-time United States magistrate judge or a part-time United States magistrate judge who serves as a full-time judicial officer may conduct any or all proceedings in a jury or nonjury civil matter and order the entry of judgment in the case, when specially designated to exercise such jurisdiction by the district court or courts he serves. Upon the consent of the parties, pursuant to their specific written request, any other part-time magistrate judge may exercise such jurisdiction, if such magistrate judge meets the bar membership requirements set forth in section 631(b)(1) and the chief judge of the district court certifies that a full-time magistrate judge is not reasonably available in accordance with guidelines established by the judicial council of the circuit. When there is more than one judge of a district court, designation under this paragraph shall be by the concurrence of a majority of all the judges of such district court, and when there is no such concurrence, then by the chief judge."],[1,"(2) If a magistrate judge is designated to exercise civil jurisdiction under paragraph (1) of this subsection, the clerk of court shall, at the time the action is filed, notify the parties of the availability of a magistrate judge to exercise such jurisdiction. The decision of the parties shall be communicated to the clerk of court. Thereafter, either the district court judge or the magistrate judge may again advise the parties of the availability of the magistrate judge, but in so doing, shall also advise the parties that they are free to withhold consent without adverse substantive consequences. Rules of court for the reference of civil matters to magistrate judges shall include procedures to protect the voluntariness of the parties' consent."],[1,"(3) Upon entry of judgment in any case referred under paragraph (1) of this subsection, an aggrieved party may appeal directly to the appropriate United States court of appeals from the judgment of the magistrate judge in the same manner as an appeal from any other judgment of a district court. The consent of the parties allows a magistrate judge designated to exercise civil jurisdiction under paragraph (1) of this subsection to direct the entry of a judgment of the district court in accordance with the Federal Rules of Civil Procedure. Nothing in this paragraph shall be construed as a limitation of any party's right to seek review by the Supreme Court of the United States."],[1,"(4) The court may, for good cause shown on its own motion, or under extraordinary circumstances shown by any party, vacate a reference of a civil matter to a magistrate judge under this subsection."],[1,"(5) The magistrate judge shall, subject to guidelines of the Judicial Conference, determine whether the record taken pursuant to this section shall be taken by electronic sound recording, by a court reporter, or by other means."],[0,"(d) The practice and procedure for the trial of cases before officers serving under this chapter shall conform to rules promulgated by the Supreme Court pursuant to section 2072 of this title."],[0,"(e) Contempt Authority.—"],[1,"(1) In general.—A United States magistrate judge serving under this chapter shall have within the territorial jurisdiction prescribed by the appointment of such magistrate judge the power to exercise contempt authority as set forth in this subsection."],[1,"(2) Summary criminal contempt authority.—A magistrate judge shall have the power to punish summarily by fine or imprisonment, or both, such contempt of the authority of such magistrate judge constituting misbehavior of any person in the magistrate judge's presence so as to obstruct the administration of justice. The order of contempt shall be issued under the Federal Rules of Criminal Procedure."],[1,"(3) Additional criminal contempt authority in civil consent and misdemeanor cases.—In any case in which a United States magistrate judge presides with the consent of the parties under subsection (c) of this section, and in any misdemeanor case proceeding before a magistrate judge under section 3401 of title 18, the magistrate judge shall have the power to punish, by fine or imprisonment, or both, criminal contempt constituting disobedience or resistance to the magistrate judge's lawful writ, process, order, rule, decree, or command. Disposition of such contempt shall be conducted upon notice and hearing under the Federal Rules of Criminal Procedure."],[1,"(4) Civil contempt authority in civil consent and misdemeanor cases.—In any case in which a United States magistrate judge presides with the consent of the parties under subsection (c) of this section, and in any misdemeanor case proceeding before a magistrate judge under section 3401 of title 18, the magistrate judge may exercise the civil contempt authority of the district court. This paragraph shall not be construed to limit the authority of a magistrate judge to order sanctions under any other statute, the Federal Rules of Civil Procedure, or the Federal Rules of Criminal Procedure."],[1,"(5) Criminal contempt penalties.—The sentence imposed by a magistrate judge for any criminal contempt provided for in paragraphs (2) and (3) shall not exceed the penalties for a Class C misdemeanor as set forth in sections 3581(b)(8) and 3571(b)(6) of title 18."],[1,"(6) Certification of other contempts to the district court.—Upon the commission of any such act—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/636?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§636. Jurisdiction, powers, and temporary assignment","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 497","url":"https://www.law.cornell.edu/uscode/text/16/497","stext":{"head":"§497. Use and occupation of lands for hotels, resorts, summer homes, stores, and facilities for industrial, commercial, educational or public uses","paras":[[0,"The Secretary of Agriculture is authorized, under such regulations as he may make and upon such terms and conditions as he may deem proper, (a) to permit the use and occupancy of suitable areas of land within the national forests, not exceeding eighty acres and for periods not exceeding thirty years, for the purpose of constructing or maintaining hotels, resorts, and any other structures or facilities necessary or desirable for recreation, public convenience, or safety; (b) to permit the use and occupancy of suitable areas of land within the national forests, not exceeding five acres and for periods not exceeding thirty years, for the purpose of constructing or maintaining summer homes and stores; (c) to permit the use and occupancy of suitable areas of land within the national forest, not exceeding eighty acres and for periods not exceeding thirty years, for the purpose of constructing or maintaining buildings, structures, and facilities for industrial or commercial purposes whenever such use is related to or consistent with other uses on the national forests; (d) to permit any State or political subdivision thereof, or any public or nonprofit agency, to use and occupy suitable areas of land within the national forests not exceeding eighty acres and for periods not exceeding thirty years, for the purpose of constructing or maintaining any buildings, structures, or facilities necessary or desirable for education or for any public use or in connection with any public activity. The authority provided by this section shall be exercised in such manner as not to preclude the general public from full enjoyment of the natural, scenic, recreational, and other aspects of the national forests."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/497?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§497. Use and occupation of lands for hotels, resorts, summer homes, stores, and facilities for industrial, commercial, educational or public uses","tname":"Conservation","by":{"0":""}},{"t":"usc","label":"42 U.S.C. § 4344","url":"https://www.law.cornell.edu/uscode/text/42/4344","by":{"0":""}},{"t":"usc","label":"16 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/16/1536","subs":["(a)(2)"],"stext":{"head":"§1536. Interagency cooperation","paras":[[0,"(a) Federal agency actions and consultations"],[0,"(1) The Secretary shall review other programs administered by him and utilize such programs in furtherance of the purposes of this chapter. All other Federal agencies shall, in consultation with and with the assistance of the Secretary, utilize their authorities in furtherance of the purposes of this chapter by carrying out programs for the conservation of endangered species and threatened species listed pursuant to section 1533 of this title."],[0,"(2) Each Federal agency shall, in consultation with and with the assistance of the Secretary, insure that any action authorized, funded, or carried out by such agency (hereinafter in this section referred to as an \"agency action\") is not likely to jeopardize the continued existence of any endangered species or threatened species or result in the destruction or adverse modification of habitat of such species which is determined by the Secretary, after consultation as appropriate with affected States, to be critical, unless such agency has been granted an exemption for such action by the Committee pursuant to subsection (h) of this section. In fulfilling the requirements of this paragraph each agency shall use the best scientific and commercial data available."],[0,"(3) Subject to such guidelines as the Secretary may establish, a Federal agency shall consult with the Secretary on any prospective agency action at the request of, and in cooperation with, the prospective permit or license applicant if the applicant has reason to believe that an endangered species or a threatened species may be present in the area affected by his project and that implementation of such action will likely affect such species."],[0,"(4) Each Federal agency shall confer with the Secretary on any agency action which is likely to jeopardize the continued existence of any species proposed to be listed under section 1533 of this title or result in the destruction or adverse modification of critical habitat proposed to be designated for such species. This paragraph does not require a limitation on the commitment of resources as described in subsection (d)."],[0,"(b) Opinion of Secretary"],[0,"(1)(A) Consultation under subsection (a)(2) with respect to any agency action shall be concluded within the 90-day period beginning on the date on which initiated or, subject to subparagraph (B), within such other period of time as is mutually agreeable to the Secretary and the Federal agency."],[0,"(B) In the case of an agency action involving a permit or license applicant, the Secretary and the Federal agency may not mutually agree to conclude consultation within a period exceeding 90 days unless the Secretary, before the close of the 90th day referred to in subparagraph (A)—"],[1,"(i) if the consultation period proposed to be agreed to will end before the 150th day after the date on which consultation was initiated, submits to the applicant a written statement setting forth—"],[2,"(I) the reasons why a longer period is required,"],[2,"(II) the information that is required to complete the consultation, and"],[2,"(III) the estimated date on which consultation will be completed; or"],[1,"(ii) if the consultation period proposed to be agreed to will end 150 or more days after the date on which consultation was initiated, obtains the consent of the applicant to such period."],[0,"The Secretary and the Federal agency may mutually agree to extend a consultation period established under the preceding sentence if the Secretary, before the close of such period, obtains the consent of the applicant to the extension."],[0,"(2) Consultation under subsection (a)(3) shall be concluded within such period as is agreeable to the Secretary, the Federal agency, and the applicant concerned."],[0,"(3)(A) Promptly after conclusion of consultation under paragraph (2) or (3) of subsection (a), the Secretary shall provide to the Federal agency and the applicant, if any, a written statement setting forth the Secretary's opinion, and a summary of the information on which the opinion is based, detailing how the agency action affects the species or its critical habitat. If jeopardy or adverse modification is found, the Secretary shall suggest those reasonable and prudent alternatives which he believes would not violate subsection (a)(2) and can be taken by the Federal agency or applicant in implementing the agency action."],[0,"(B) Consultation under subsection (a)(3), and an opinion issued by the Secretary incident to such consultation, regarding an agency action shall be treated respectively as a consultation under subsection (a)(2), and as an opinion issued after consultation under such subsection, regarding that action if the Secretary reviews the action before it is commenced by the Federal agency and finds, and notifies such agency, that no significant changes have been made with respect to the action and that no significant change has occurred regarding the information used during the initial consultation."],[0,"(4) If after consultation under subsection (a)(2), the Secretary concludes that—"],[1,"(A) the agency action will not violate such subsection, or offers reasonable and prudent alternatives which the Secretary believes would not violate such subsection;"],[1,"(B) the taking of an endangered species or a threatened species incidental to the agency action will not violate such subsection; and"],[1,"(C) if an endangered species or threatened species of a marine mammal is involved, the taking is authorized pursuant to section 1371(a)(5) of this title;"],[0,"the Secretary shall provide the Federal agency and the applicant concerned, if any, with a written statement that—"],[1,"(i) specifies the impact of such incidental taking on the species,"],[1,"(ii) specifies those reasonable and prudent measures that the Secretary considers necessary or appropriate to minimize such impact,"],[1,"(iii) in the case of marine mammals, specifies those measures that are necessary to comply with section 1371(a)(5) of this title with regard to such taking, and"],[1,"(iv) sets forth the terms and conditions (including, but not limited to, reporting requirements) that must be complied with by the Federal agency or applicant (if any), or both, to implement the measures specified under clauses (ii) and (iii)."],[0,"(c) Biological assessment"],[0,"(1) To facilitate compliance with the requirements of subsection (a)(2), each Federal agency shall, with respect to any agency action of such agency for which no contract for construction has been entered into and for which no construction has begun on November 10, 1978, request of the Secretary information whether any species which is listed or proposed to be listed may be present in the area of such proposed action. If the Secretary advises, based on the best scientific and commercial data available, that such species may be present, such agency shall conduct a biological assessment for the purpose of identifying any endangered species or threatened species which is likely to be affected by such action. Such assessment shall be completed within 180 days after the date on which initiated (or within such other period as is mutually agreed to by the Secretary and such agency, except that if a permit or license applicant is involved, the 180-day period may not be extended unless such agency provides the applicant, before the close of such period, with a written statement setting forth the estimated length of the proposed extension and the reasons therefor) and, before any contract for construction is entered into and before construction is begun with respect to such action. Such assessment may be undertaken as part of a Federal agency's compliance with the requirements of section 102 of the National Environmental Policy Act of 1969 (42 U.S.C. 4332)."],[0,"(2) Any person who may wish to apply for an exemption under subsection (g) of this section for that action may conduct a biological assessment to identify any endangered species or threatened species which is likely to be affected by such action. Any such biological assessment must, however, be conducted in cooperation with the Secretary and under the supervision of the appropriate Federal agency."],[0,"(d) Limitation on commitment of resources"],[0,"After initiation of consultation required under subsection (a)(2), the Federal agency and the permit or license applicant shall not make any irreversible or irretrievable commitment of resources with respect to the agency action which has the effect of foreclosing the formulation or implementation of any reasonable and prudent alternative measures which would not violate subsection (a)(2) of this section."],[0,"(e) Endangered Species Committee"],[0,"(1) There is established a committee to be known as the Endangered Species Committee (hereinafter in this section referred to as the \"Committee\")."],[0,"(2) The Committee shall review any application submitted to it pursuant to this section and determine in accordance with subsection (h) of this section whether or not to grant an exemption from the requirements of subsection (a)(2) of this section for the action set forth in such application."],[0,"(3) The Committee shall be composed of seven members as follows:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/1536?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1536. Interagency cooperation","tname":"Conservation","by":{"0":""}},{"t":"usc","label":"49 U.S.C. § 303","url":"https://www.law.cornell.edu/uscode/text/49/303","stext":{"head":"§303. Policy on lands, wildlife and waterfowl refuges, and historic sites","paras":[[0,"(a) It is the policy of the United States Government that special effort should be made to preserve the natural beauty of the countryside and public park and recreation lands, wildlife and waterfowl refuges, and historic sites."],[0,"(b) The Secretary of Transportation shall cooperate and consult with the Secretaries of the Interior, Housing and Urban Development, and Agriculture, and with the States, in developing transportation plans and programs that include measures to maintain or enhance the natural beauty of lands crossed by transportation activities or facilities."],[0,"(c) Approval of Programs and Projects.—Subject to subsections (d) and (h), the Secretary may approve a transportation program or project (other than any project for a park road or parkway under section 204 1 of title 23) requiring the use of publicly owned land of a public park, recreation area, or wildlife and waterfowl refuge of national, State, or local significance, or land of an historic site of national, State, or local significance (as determined by the Federal, State, or local officials having jurisdiction over the park, area, refuge, or site) only if—"],[1,"(1) there is no prudent and feasible alternative to using that land; and"],[1,"(2) the program or project includes all possible planning to minimize harm to the park, recreation area, wildlife and waterfowl refuge, or historic site resulting from the use."],[0,"(d) De Minimis Impacts.—"],[1,"(1) Requirements.—"],[2,"(A) Requirements for historic sites.—The requirements of this section shall be considered to be satisfied with respect to an area described in paragraph (2) if the Secretary determines, in accordance with this subsection, that a transportation program or project will have a de minimis impact on the area."],[2,"(B) Requirements for parks, recreation areas, and wildlife or waterfowl refuges.—The requirements of subsection (c)(1) shall be considered to be satisfied with respect to an area described in paragraph (3) if the Secretary determines, in accordance with this subsection, that a transportation program or project will have a de minimis impact on the area. The requirements of subsection (c)(2) with respect to an area described in paragraph (3) shall not include an alternatives analysis."],[2,"(C) Criteria.—In making any determination under this subsection, the Secretary shall consider to be part of a transportation program or project any avoidance, minimization, mitigation, or enhancement measures that are required to be implemented as a condition of approval of the transportation program or project."],[1,"(2) Historic sites.—With respect to historic sites, the Secretary may make a finding of de minimis impact only if—"],[2,"(A) the Secretary has determined, in accordance with the consultation process required under section 306108 of title 54, United States Code,2 that—"],[3,"(i) the transportation program or project will have no adverse effect on the historic site; or"],[3,"(ii) there will be no historic properties affected by the transportation program or project;"],[2,"(B) the finding of the Secretary has received written concurrence from the applicable State historic preservation officer or tribal historic preservation officer (and from the Advisory Council on Historic Preservation if the Council is participating in the consultation process); and"],[2,"(C) the finding of the Secretary has been developed in consultation with parties consulting as part of the process referred to in subparagraph (A)."],[1,"(3) Parks, recreation areas, and wildlife or waterfowl refuges.—With respect to parks, recreation areas, or wildlife or waterfowl refuges, the Secretary may make a finding of de minimis impact only if—"],[2,"(A) the Secretary has determined, after public notice and opportunity for public review and comment, that the transportation program or project will not adversely affect the activities, features, and attributes of the park, recreation area, or wildlife or waterfowl refuge eligible for protection under this section; and"],[2,"(B) the finding of the Secretary has received concurrence from the officials with jurisdiction over the park, recreation area, or wildlife or waterfowl refuge."],[0,"(e) Satisfaction of Requirements for Certain Historic Sites.—"],[1,"(1) In general.—The Secretary shall—"],[2,"(A) align, to the maximum extent practicable, the requirements of this section with the requirements of the National Environmental Policy Act of 1969 (42 U.S.C. 4321 et seq.) and section 306108 of title 54, including implementing regulations; and"],[2,"(B) not later than 90 days after the date of enactment of this subsection, coordinate with the Secretary of the Interior and the Executive Director of the Advisory Council on Historic Preservation (referred to in this subsection as the \"Council\") to establish procedures to satisfy the requirements described in subparagraph (A) (including regulations)."],[1,"(2) Avoidance alternative analysis.—"],[2,"(A) In general.—If, in an analysis required under the National Environmental Policy Act of 1969 (42 U.S.C. 4321 et seq.), the Secretary determines that there is no feasible or prudent alternative to avoid use of a historic site, the Secretary may—"],[3,"(i) include the determination of the Secretary in the analysis required under that Act;"],[3,"(ii) provide a notice of the determination to—"],[4,"(I) each applicable State historic preservation officer and tribal historic preservation officer;"],[4,"(II) the Council, if the Council is participating in the consultation process under section 306108 of title 54; and"],[4,"(III) the Secretary of the Interior; and"],[3,"(iii) request from the applicable preservation officer, the Council, and the Secretary of the Interior a concurrence that the determination is sufficient to satisfy subsection (c)(1)."],[2,"(B) Concurrence.—If the applicable preservation officer, the Council, and the Secretary of the Interior each provide a concurrence requested under subparagraph (A)(iii), no further analysis under subsection (c)(1) shall be required."],[2,"(C) Publication.—A notice of a determination, together with each relevant concurrence to that determination, under subparagraph (A) shall—"],[3,"(i) be included in the record of decision or finding of no significant impact of the Secretary; and"],[3,"(ii) be posted on an appropriate Federal website by not later than 3 days after the date of receipt by the Secretary of all concurrences requested under subparagraph (A)(iii)."],[1,"(3) Aligning historical reviews.—"],[2,"(A) In general.—If the Secretary, the applicable preservation officer, the Council, and the Secretary of the Interior concur that no feasible and prudent alternative exists as described in paragraph (2), the Secretary may provide to the applicable preservation officer, the Council, and the Secretary of the Interior notice of the intent of the Secretary to satisfy subsection (c)(2) through the consultation requirements of section 306108 of title 54."],[2,"(B) Satisfaction of conditions.—To satisfy subsection (c)(2), the applicable preservation officer, the Council, and the Secretary of the Interior shall concur in the treatment of the applicable historic site described in the memorandum of agreement or programmatic agreement developed under section 306108 of title 54."],[0,"(f) References to Past Transportation Environmental Authorities.—"],[1,"(1) Section 4(f) requirements.—The requirements of this section are commonly referred to as section 4(f) requirements (see section 4(f) of the Department of Transportation Act (Public Law 89–670; 80 Stat. 934) as in effect before the repeal of that section)."],[1,"(2) Section 106 requirements.—The requirements of section 306108 of title 54 are commonly referred to as section 106 requirements (see section 106 of the National Historic Preservation Act of 1966 (Public Law 89–665; 80 Stat. 917) as in effect before the repeal of that section)."],[0,"(g) Bridge Exemption From Consideration.—A common post-1945 concrete or steel bridge or culvert (as described in 77 Fed. Reg. 68790) that is exempt from individual review under section 306108 of title 54 shall be exempt from consideration under this section."],[0,"(h) Rail and Transit.—"],[1,"(1) In general.—Improvements to, or the maintenance, rehabilitation, or operation of, railroad or rail transit lines or elements thereof that are in use or were historically used for the transportation of goods or passengers shall not be considered a use of a historic site under subsection (c), regardless of whether the railroad or rail transit line or element thereof is listed on, or eligible for listing on, the National Register of Historic Places."],[1,"(2) Exceptions.—"],[2,"(A) In general.—Paragraph (1) shall not apply to—"],[3,"(i) stations; or"],[3,"(ii) bridges or tunnels located on—"],[4,"(I) railroad lines that have been abandoned; or"],[4,"(II) transit lines that are not in use."],[2,"(B) Clarification with respect to certain bridges and tunnels.—The bridges and tunnels referred to in subparagraph (A)(ii) do not include bridges or tunnels located on railroad or transit lines—"],[3,"(i) over which service has been discontinued; or"],[3,"(ii) that have been railbanked or otherwise reserved for the transportation of goods or passengers."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/303?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§303. Policy on lands, wildlife and waterfowl refuges, and historic sites","tname":"Transportation","by":{"0":""}},{"t":"usc","label":"43 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/43/1701","by":{"0":""}},{"t":"usc","label":"43 U.S.C. § 1761","url":"https://www.law.cornell.edu/uscode/text/43/1761","subs":["(a)(6)"],"by":{"0":""}}]};